  if ('IntersectionObserver' in window) { const io = new IntersectionObserver(G => G.forEach(g => g.target.classList.toggle('ekran-disi', !g.isIntersecting)), { rootMargin: '80px' });
    const izle = () => document.querySelectorAll('.tm-gk:not([data-io]), .tm-oge:not([data-io]), .ps-ic:not([data-io])').forEach(e => { e.dataset.io = '1'; io.observe(e); });
    new MutationObserver(() => { clearTimeout(izle.z); izle.z = setTimeout(izle, 150); }).observe(document.body, { childList: true, subtree: true }); izle(); }
  // K-716by: öğretmen girişi — e-posta + kendi şifresi (telefon hatırlar); ilk girişte ve şifre unutulunca e-posta kodu, ardından şifre belirleme
  $('#sifreGoz').onclick = () => { const i = $('#sifre'); i.classList.toggle('pin-gizli'); i.focus(); };   // K-716cp: şifre alanı düz metin + nokta (Apple güçlü parola önerisi çıkmasın)
  $('#sifreGiris').onclick = async () => {
    const e = $('#eposta').value.trim().toLowerCase(), p = $('#sifre').value;
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e)) { $('#girisBilgi').textContent = 'E-posta adresini yazın.'; $('#eposta').focus(); return; }
    if (!p) { $('#girisBilgi').textContent = 'Şifrenizi yazın. İlk kez giriyorsanız ya da şifreniz yoksa aşağıdan e-postanıza kod isteyin.'; $('#sifre').focus(); return; }
    $('#sifreGiris').disabled = true; $('#girisBilgi').textContent = 'Giriş yapılıyor…';
    const { error } = await israrla(() => sb.auth.signInWithPassword({ email: e, password: p }));
    $('#sifreGiris').disabled = false;
    if (error) { $('#girisBilgi').textContent = agHatasi(error) ? 'İnternet bağlantısı yok gibi; yeniden deneyin.' : /invalid|credentials/i.test(error.message || '') ? 'E-posta ya da şifre yanlış. Henüz şifre belirlemediyseniz aşağıdan kodla girin.' : 'Giriş olmadı: ' + hataYaz(error); return; }
    try { localStorage.setItem('atlas-hatirla', '1'); localStorage.setItem('atlas-son-eposta', e); } catch (e_) {}
    $('#girisBilgi').textContent = ''; basla();
  };
  const sifreAdimi = e => {   // kodla girişten sonra: kendi şifresini belirler (ya da geçer)
    $('#adim2').classList.add('gizli'); $('#adim3').classList.remove('gizli'); $('#girisBilgi').textContent = ''; setTimeout(() => $('#yeniSifre').focus(), 50);
  };
  $('#sifreKaydet').onclick = async () => {
    const p1 = $('#yeniSifre').value, p2 = $('#yeniSifre2').value;
    if (!/^\d{6}$/.test(p1)) { $('#girisBilgi').textContent = 'Şifre 6 haneli bir sayı olsun.'; return; }   // K-716bz: rakam şifre
    if (/^(\d)\1+$/.test(p1) || '0123456789012345'.includes(p1) || '9876543210987654'.includes(p1)) { $('#girisBilgi').textContent = 'Bu şifre çok kolay tahmin edilir; başka rakamlar seçin.'; return; }
    if (p1 !== p2) { $('#girisBilgi').textContent = 'İki şifre aynı değil.'; return; }
    $('#sifreKaydet').disabled = true; $('#girisBilgi').textContent = 'Kaydediliyor…';
    const { error } = await sb.auth.updateUser({ password: p1, data: { sifre_var: true } });
    $('#sifreKaydet').disabled = false;
    if (error && !/different from the old|same password|should be different/i.test(error.message || '')) { const en = (String(error.message || '').match(/at least (\d+)/i) || [])[1]; $('#girisBilgi').textContent = en ? `Şifre en az ${en} rakam olmalı.` : /weak|pwned|leaked|characters/i.test(error.message || '') ? 'Bu şifre çok kolay ya da sızmış listelerde var; başka rakamlar seçin.' : 'Şifre kaydedilemedi: ' + hataYaz(error); return; }
    try { localStorage.removeItem('atlas-sifre-gerek'); } catch (e) {}
    $('#girisBilgi').textContent = ''; $('#adim3').classList.add('gizli'); basla();
  };
  $('#sifreGec').onclick = () => { $('#adim3').classList.add('gizli'); $('#girisBilgi').textContent = ''; basla(); };
  $('#yeniSifre2').addEventListener('keydown', ev => { if (ev.key === 'Enter') $('#sifreKaydet').click(); });
  $('#kodGonder').onclick = async () => {
    const e = $('#eposta').value.trim().toLowerCase();
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e)) { $('#girisBilgi').textContent = 'E-posta adresini yazın.'; return; }
    $('#kodGonder').disabled = true; $('#girisBilgi').textContent = 'Gönderiliyor…';
    const { error } = await sb.auth.signInWithOtp({ email: e, options: { shouldCreateUser: true } });
    $('#kodGonder').disabled = false;
    if (error) { $('#girisBilgi').textContent = 'Kod gönderilemedi: ' + hataYaz(error); return; }
    $('#girisBilgi').textContent = 'Kod gönderildi. E-postanızı kontrol edin (istenmeyen klasörüne de bakın).';
    $('#adim1').classList.add('gizli'); $('#adim2').classList.remove('gizli'); $('#kod').focus();
  };
  $('#girisYap').onclick = async () => {
    const e = $('#eposta').value.trim().toLowerCase(), k = $('#kod').value.replace(/\D/g, '');
    if (k.length < 6 || k.length > 10) { $('#girisBilgi').textContent = 'E-postadaki kodun tamamını yazın.'; return; }
    $('#girisYap').disabled = true;
    try { localStorage.setItem('atlas-hatirla', $('#hatirla').checked ? '1' : '0'); } catch (e) {}
    let { error } = await israrla(() => sb.auth.verifyOtp({ email: e, token: k, type: 'email' }));
    if (error && !agHatasi(error)) { const r2 = await sb.auth.verifyOtp({ email: e, token: k, type: 'signup' }).catch(er => ({ error: er })); if (!r2.error) error = null; }   // K-526: ilk girişte "Confirm signup" kodu
    $('#girisYap').disabled = false;
    if (error) { $('#girisBilgi').textContent = 'Kod doğru değil ya da süresi doldu.'; return; }
    $('#girisBilgi').textContent = ''; try { localStorage.setItem('atlas-son-eposta', e); } catch (e_) {}
    sifreAdimi(e);   // K-716by: koddan sonra kendi şifresini belirlesin
  };
  $('#kod').addEventListener('keydown', ev => { if (ev.key === 'Enter') $('#girisYap').click(); });
  $('#eposta').addEventListener('keydown', ev => { if (ev.key === 'Enter') { ev.preventDefault(); $('#sifre').focus(); } });
  $('#sifre').addEventListener('keydown', ev => { if (ev.key === 'Enter') { ev.preventDefault(); $('#sifreGiris').click(); } });
  $('#geri').onclick = () => { $('#adim1').classList.remove('gizli'); $('#adim2').classList.add('gizli'); $('#adim3').classList.add('gizli'); $('#girisBilgi').textContent = ''; };
  $('#cikis').onclick = async () => { await sb.auth.signOut({ scope: 'local' }); location.reload(); };

  // Masaüstü simgesi: Edge / Chrome "uygulama olarak yükle" (tek tıkla açılır, adres çubuğu yok).
  let kurulum = null;
  const yukleDugmeleri = () => ['#yukle', '#yukleGiris'].map(x => $(x)).filter(Boolean);
  // K-520: girişte tek düğme — tarayıcı tek tıkla yüklemeyi teklif ediyorsa düğme, etmiyorsa anlatım bağlantısı (ikisi birden görünmez)
  const kurBag = () => document.querySelector('.giris .kurlink');
  const yukleGoster = var_ => { yukleDugmeleri().forEach(b => b.classList.toggle('gizli', !var_)); if (kurBag()) kurBag().classList.toggle('gizli', var_); };
  window.addEventListener('beforeinstallprompt', e => { e.preventDefault(); kurulum = e; yukleGoster(true); });
  window.addEventListener('appinstalled', () => { kurulum = null; yukleGoster(false); });
  yukleDugmeleri().forEach(b => b.onclick = async () => { if (!kurulum) return; kurulum.prompt(); await kurulum.userChoice.catch(() => {}); kurulum = null; yukleGoster(false); });

  // Yan menüdeki saat: saniye ibresi her saniye tık diye atlar
  (function saat() {
    const AY = ['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık'], GUN = ['Pazar','Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi'];
    const p2 = n => String(n).padStart(2, '0');
    const ciz = () => {
      const d = new Date(), h = d.getHours(), m = d.getMinutes(), sn = d.getSeconds();
      const a = document.getElementById('akrep'); if (!a) return;
      a.setAttribute('transform', `rotate(${(h % 12) * 30 + m * .5} 50 50)`);
      document.getElementById('yelkovan').setAttribute('transform', `rotate(${m * 6 + sn * .1} 50 50)`);
      const g = document.getElementById('saniye'); g.setAttribute('transform', `rotate(${sn * 6} 50 50)`);
      g.classList.remove('tik'); void g.getBBox(); g.classList.add('tik');
      document.getElementById('saatSD').textContent = `${p2(h)}.${p2(m)}`;
      const s_ = document.getElementById('saatSn'); s_.textContent = p2(sn); s_.classList.remove('at'); void s_.offsetWidth; s_.classList.add('at');
      document.getElementById('saatTarih').innerHTML = `${d.getDate()} ${AY[d.getMonth()]} ${d.getFullYear()}<br><b>${GUN[d.getDay()]}</b>`;
    };
    ciz(); setTimeout(() => { ciz(); setInterval(ciz, 1000); }, 1000 - new Date().getMilliseconds());
  })();

