          const o = B[0]; let k = null;
          for (const yaniBos of [true, false]) { for (let x = GZ_AYRILAN + 1; x <= o.kapasite; x++) { if (doluMu(o, x)) continue; const y = komsuKoltuk(o.id, x); if (yaniBos && y && doluMu(o, y)) continue; k = x; break; } if (k) break; }
