    const tumSalon = Object.keys((D.program || {}).siniflar || {}).filter(s => /^\d+-[A-ZÇĞİÖŞÜ]$/.test(s)).sort(sinifSira);
    let sec = sinavlar[0] || null, plan = null, acikSalon = null, kapali = new Set(), tohum = 1;
