    const nobetciler = () => { if (!sec) return []; return nobetBugun(nobetN, new Date(sec.tarih + 'T12:00:00')).filter(x => !x.yer.startsWith('Nöbetçi Müdür')).map(x => baslik(x.ad)).sort((a, b) => a.localeCompare(b, tr)); };
