        const salonlar = {}; Object.entries(plan.salonlar).forEach(([x, L]) => { salonlar[x] = L.slice().sort((a, b) => a.sira - b.sira).map(r => [r.sira, String(r.no), r.ad, r.sinif, r.ders]); });
