      const ileri = () => { pi++; if (pi >= parcalar.length) return false; p = parcalar[pi].o; son = p + parcalar[pi].l; return true; };
      const u8 = () => { if (p >= son && !ileri()) return 0; return W[p++]; }, u16 = () => u8() | (u8() << 8), u32 = () => (u16() | (u16() << 16)) >>> 0;
